type View = "default" | "my" | "shared" | "system" | "custom" | "service-detail" | "create" | "edit" | "custom-create" | "provider-config";
type ScopeDef = { value: string; label: string; description: string; group?: string; risk?: "STANDARD" | "SENSITIVE" | "RESTRICTED" };
type ServiceCard = { key:string; name:string; provider:string; mark:string; bg:string; fg:string; authType?:string; oauth?:boolean; baseUrl?:string; scopes?:ScopeDef[]; defaultScopes?:string[]; scopeGroups?:string[]; customId?:string };
type CustomDraft = { name:string; key:string; authType:"OAUTH2"|"API_KEY"|"BEARER"|"BASIC"|"CUSTOM_HEADER"|"NONE"; parameterKey:string; parameterLabel:string; parameterType:"QUERY"|"HEADER"; baseUrl:string; oauthAuthUrl:string; oauthTokenUrl:string; oauthRevokeUrl:string; oauthClientId:string; oauthClientSecret:string; accountUrl:string; scopes:ScopeDef[]; defaultScopes:string[] };

